-- Realistic Supabase migration (AC-005-06): lowercase keywords, comments,
-- schema-qualified and quoted names, $$ function and trigger bodies.

/* Block comment; with a semicolon and a fake statement:
   create table public.not_a_table (id int); */

create table if not exists public.profiles (
  id uuid not null references auth.users on delete cascade, -- owner; 1:1 with auth.users
  username text unique,
  "avatarUrl" text,
  updated_at timestamp with time zone default now(),
  constraint username_length check (char_length(username) >= 3),
  primary key (id)
);

create table "public"."Team Members" (
  id bigint generated by default as identity primary key,
  team_id bigint not null,
  user_id uuid not null references public.profiles (id),
  role text not null default 'member; viewer' -- semicolon inside a string
);

-- Read by the restrictive policy in the next file.
create table public.bans (
  user_id uuid not null references auth.users on delete cascade,
  reason text not null
);

-- A function whose $$ body contains semicolons and SQL-looking text.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
begin
  -- create table public.fake (id int);
  insert into public.profiles (id, username)
  values (new.id, new.raw_user_meta_data->>'username');
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

create function public.is_team_member(tid bigint)
returns boolean
language sql stable
as $body$
  select exists (
    select 1 from "public"."Team Members" m
    where m.team_id = tid and m.user_id = auth.uid()
  );
$body$;

comment on table public.profiles is 'Public profile; one row per user.';
